def describe(room):
    if room == "hall":
        return "A dusty hall. Doors lead north and east."
    elif room == "library":
        return "Shelves of old books. The only door is south."
    return "A dark room."

def next_room(room, direction):
    if room == "hall" and direction == "north":
        return "library"
    if room == "library" and direction == "south":
        return "hall"
    if room == "hall" and direction == "east":
        return "exit"
    return room

def main():
    room = "hall"
    while room != "exit":
        print(describe(room))
        direction = input("Which way? ").strip().lower()
        room = next_room(room, direction)
    print("You escaped!")

main()

