class Category:
    def __init__(self, name, limit):
        self.name = name
        self.limit = limit
        self.transactions = []

    def spend(self, amount, note):
        if amount <= 0:
            raise ValueError("amount must be positive")
        self.transactions.append((amount, note))

    def spent(self):
        total = 0
        for amount, note in self.transactions:
            total += amount
        return total

    def remaining(self):
        return self.limit - self.spent()

food = Category("Food", 300)
food.spend(42.5, "groceries")
food.spend(18, "lunch")
print(food.spent(), food.remaining())

