def nested_sum(items):
    """Sum the numbers in a list that may contain lists, to any depth."""
    total = 0
    for item in items:
        if isinstance(item, list):
            total += nested_sum(item)
        else:
            total += item
    return total

def fib_loop(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

print(nested_sum([1, [2, 3], [4, [5, [6]]]]))
print(fib_loop(10), fib_loop(50))

