"""budget.py - core logic. No input() or print() except in tests."""

def add_transaction(data, amount, category, note):
    """Append a transaction dict to data["transactions"] and return it."""
    if amount <= 0:
        raise ValueError("amount must be positive")
    if category not in data["categories"]:
        raise ValueError(f"unknown category: {category}")
    tx = {"amount": amount, "category": category, "note": note}
    data["transactions"].append(tx)
    return tx

def spent_by_category(data):
    """Return {category: total spent} for every category."""
    totals = {name: 0 for name in data["categories"]}
    for tx in data["transactions"]:
        totals[tx["category"]] += tx["amount"]
    return totals

def test_budget():
    data = {"categories": {"Food": 300, "Rent": 1200}, "transactions": []}
    add_transaction(data, 12.5, "Food", "lunch")
    add_transaction(data, 1200, "Rent", "October")
    assert spent_by_category(data) == {"Food": 12.5, "Rent": 1200}
    print("budget tests passed")

test_budget()

